// Generated by GitHub Copilot
import { useState, useEffect, useMemo, useRef } from 'react'
import { useNavigate } from 'react-router-dom'
import { FiDollarSign, FiCreditCard, FiCheck, FiX, FiPlus, FiClock, FiAlertCircle } from 'react-icons/fi'
import PageHeader from '../../components/ui/PageHeader.jsx'
import Card, { CardBody, CardHeader } from '../../components/ui/Card.jsx'
import Badge from '../../components/ui/Badge.jsx'
import Button from '../../components/ui/Button.jsx'
import Select from '../../components/ui/Select.jsx'
import Input from '../../components/ui/Input.jsx'
import Modal from '../../components/ui/Modal.jsx'
import { memberLoanApi } from '../../api/memberLoanApi.js'
import { formatCurrency, formatDate } from '../../utils/format.js'
import Loader from '../../components/ui/Loader.jsx'

/** Member loans page with summary and history. */
export default function MemberLoans() {
  const navigate = useNavigate()
  const [loans, setLoans] = useState([])
  const [summary, setSummary] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  // Apply for loan modal
  const [applyModalOpen, setApplyModalOpen] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [formData, setFormData] = useState({
    amount: '',
    dateBorrowed: '',
    expectedReturn: '',
    purpose: '',
    notes: '',
  })

  // Success message
  const [successMessage, setSuccessMessage] = useState('')

  // Loan requests
  const [loanRequests, setLoanRequests] = useState([])
  const [loanRequestsLoading, setLoanRequestsLoading] = useState(false)
  const [availableFunds, setAvailableFunds] = useState(null)

  // Filters
  const [statusFilter, setStatusFilter] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)

  const fetchData = async () => {
    setLoading(true)
    setError('')
    
    try {
      // Fetch loans with filters
      const params = { page: currentPage, limit: 10 }
      if (statusFilter) params.status = statusFilter

      const loansRes = await memberLoanApi.getMyLoans(params)
      setLoans(loansRes.loans)
      setTotalPages(loansRes.pagination.totalPages)
    } catch (err) {
      setError(err.message || 'Failed to load loans')
    }
    
    try {
      // Fetch summary independently
      const summaryRes = await memberLoanApi.getMyLoanSummary()
      setSummary(summaryRes)
    } catch (err) {
      // Silently fail summary fetch - loans data is more important
      console.error('Failed to load loan summary:', err)
    } finally {
      setLoading(false)
    }
  }

  const fetchLoanRequests = async () => {
    setLoanRequestsLoading(true)
    try {
      const data = await memberLoanApi.getMyLoanRequests()
      setLoanRequests(data)
    } catch {
      // silently fail
    } finally {
      setLoanRequestsLoading(false)
    }
  }

  const fetchAvailableFunds = async () => {
    try {
      const funds = await memberLoanApi.getAvailableFunds()
      setAvailableFunds(funds)
    } catch {
      // silently fail
    }
  }

  useEffect(() => {
    fetchData()
    fetchLoanRequests()
    fetchAvailableFunds()
  }, [currentPage, statusFilter])

  // Keep the queue position fresh: refetch on tab focus, and poll every 30s
  // only while the tab is visible and the member has a pending request.
  const hasPendingRef = useRef(false)
  useEffect(() => {
    hasPendingRef.current = loanRequests.some((r) => r.status === 'pending')
  }, [loanRequests])

  useEffect(() => {
    const refetch = () => {
      fetchLoanRequests()
      fetchAvailableFunds()
    }
    window.addEventListener('focus', refetch)
    const pollId = setInterval(() => {
      if (document.visibilityState === 'visible' && hasPendingRef.current) refetch()
    }, 30000)
    return () => {
      window.removeEventListener('focus', refetch)
      clearInterval(pollId)
    }
  }, [])


  const handleFormChange = (field) => (e) => {
    setFormData((prev) => ({ ...prev, [field]: e.target.value }))
  }

  const handleSubmitApplication = async () => {
    if (!isFormValid) return
    setSubmitting(true)
    try {
      await memberLoanApi.applyForLoan({
        amount: Number(formData.amount),
        monthRequired: formData.dateBorrowed,
        expectedReturn: formData.expectedReturn || null,
        purpose: formData.purpose,
        notes: formData.notes,
      })
      setApplyModalOpen(false)
      setFormData({ amount: '', dateBorrowed: '', expectedReturn: '', purpose: '', notes: '' })
      setSuccessMessage('Loan application submitted successfully! It is now pending review.')
      setTimeout(() => setSuccessMessage(''), 5000)
      await fetchLoanRequests()
    } catch (err) {
      console.error('Failed to submit loan request:', err)
    } finally {
      setSubmitting(false)
    }
  }

  const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

  // Members may request a loan for the current month or up to 3 months ahead.
  const monthOptions = useMemo(() => {
    const now = new Date()
    return Array.from({ length: 4 }, (_, i) => {
      const d = new Date(now.getFullYear(), now.getMonth() + i, 1)
      const ym = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
      return { value: ym, label: `${monthNames[d.getMonth()]} ${d.getFullYear()}` }
    })
  }, [])

  const formatMonth = (ym) => {
    if (!ym) return '—'
    const [y, m] = ym.split('-')
    return `${monthNames[parseInt(m) - 1]} ${y}`
  }

  // Return date must fall after the selected loan month.
  const returnDateMin = useMemo(() => {
    if (!formData.dateBorrowed) return ''
    const [y, m] = formData.dateBorrowed.split('-').map(Number)
    const d = new Date(y, m, 1)
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-01`
  }, [formData.dateBorrowed])

  const isFormValid =
    Number(formData.amount) > 0 &&
    !!formData.dateBorrowed &&
    !!formData.expectedReturn &&
    formData.expectedReturn >= returnDateMin &&
    !!formData.purpose

  const statusBadgeVariant = (status) => {
    if (status === 'pending') return 'warning'
    if (status === 'approved') return 'success'
    if (status === 'rejected') return 'danger'
    if (status === 'withdrawn') return 'slate'
    return 'slate'
  }

  const handleWithdraw = async (requestId) => {
    if (!window.confirm('Are you sure you want to withdraw this loan request?')) return
    try {
      await memberLoanApi.withdrawLoanRequest(requestId)
      setSuccessMessage('Loan request withdrawn successfully.')
      setTimeout(() => setSuccessMessage(''), 5000)
      await fetchLoanRequests()
    } catch (err) {
      console.error('Failed to withdraw loan request:', err)
    }
  }

  const summaryCards = summary ? [
    {
      label: 'Total Borrowed',
      value: formatCurrency(summary.totalBorrowed),
      icon: FiDollarSign,
      tone: 'brand',
    },
    {
      label: 'Remaining Balance',
      value: formatCurrency(summary.totalRemaining),
      icon: FiCreditCard,
      tone: 'amber',
    },
    {
      label: 'Active Loans',
      value: summary.activeLoans.toString(),
      icon: FiCheck,
      tone: 'green',
    },
    {
      label: 'Closed Loans',
      value: summary.closedLoans.toString(),
      icon: FiX,
      tone: 'slate',
    },
  ] : []

  if (loading && !summary) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <Loader label="Loading loans…" />
      </div>
    )
  }

  return (
    <div>
      <PageHeader
        title="My Loans"
        description="View your loan history and summary"
      />

      {successMessage && (
        <div className="mb-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-700">
          {successMessage}
        </div>
      )}

      {error && (
        <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {error}
        </div>
      )}

      {/* Apply for Loan */}
      <div className="mb-6 flex items-center justify-end">
        <Button icon={FiPlus} onClick={() => setApplyModalOpen(true)}>
          Apply for Loan
        </Button>
      </div>

      {/* Apply for Loan Modal */}
      <Modal
        open={applyModalOpen}
        onClose={() => setApplyModalOpen(false)}
        title="Apply for Loan"
        size="md"
        footer={
          <>
            <Button variant="secondary" onClick={() => setApplyModalOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmitApplication} disabled={submitting || !isFormValid}>
              {submitting ? 'Submitting…' : 'Submit Application'}
            </Button>
          </>
        }
      >
        <div className="space-y-5">
          {/* Disclaimer */}
          <div className="rounded-lg border border-blue-100 bg-blue-50 px-4 py-3">
            <p className="text-xs text-blue-700 leading-relaxed">
              <strong>Note:</strong> Loan approval is subject to fund availability and is processed on a priority basis. We appreciate your understanding, Jazak Allah Khair.
            </p>
          </div>

          {/* Available balance */}
          <div className="flex items-center justify-between rounded-lg border border-green-100 bg-green-50 px-4 py-3">
            <span className="text-sm font-medium text-green-800">Available balance</span>
            <span className="text-base font-semibold text-green-800">
              {availableFunds === null ? '—' : formatCurrency(availableFunds)}
            </span>
          </div>

          <Input
            label="Loan Amount (₹)"
            name="amount"
            type="number"
            min="1"
            placeholder="Enter amount you wish to borrow"
            value={formData.amount}
            onChange={handleFormChange('amount')}
          />
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <Select
              label="Month for which loan is required"
              name="dateBorrowed"
              value={formData.dateBorrowed}
              onChange={handleFormChange('dateBorrowed')}
            >
              <option value="" disabled>Select month</option>
              {monthOptions.map((opt) => (
                <option key={opt.value} value={opt.value}>{opt.label}</option>
              ))}
            </Select>
            <Input
              label="Expected Return Date"
              name="expectedReturn"
              type="date"
              min={returnDateMin || undefined}
              disabled={!formData.dateBorrowed}
              value={formData.expectedReturn}
              onChange={handleFormChange('expectedReturn')}
            />
          </div>
          <Select
            label="Purpose"
            name="purpose"
            value={formData.purpose}
            onChange={handleFormChange('purpose')}
          >
            <option value="" disabled>Select purpose</option>
            <option value="personal">Personal</option>
            <option value="medical">Medical</option>
            <option value="education">Education</option>
            <option value="business">Business</option>
            <option value="home">Home</option>
            <option value="other">Other</option>
          </Select>
          <div>
            <label className="mb-1.5 block text-sm font-medium text-slate-700">
              Notes (optional)
            </label>
            <textarea
              rows={3}
              className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-800 placeholder:text-slate-400 focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-500"
              placeholder="Any additional details about your loan request"
              value={formData.notes}
              onChange={handleFormChange('notes')}
            />
          </div>
        </div>
      </Modal>

      {/* Summary Cards */}
      {summary && (
        <div className="mb-6 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {summaryCards.map((card) => {
            const Icon = card.icon
            return (
              <Card key={card.label}>
                <CardBody className="flex items-center gap-4">
                  <span className="flex h-12 w-12 items-center justify-center rounded-lg bg-slate-100 text-slate-600">
                    <Icon className="h-6 w-6" />
                  </span>
                  <div>
                    <p className="text-xs text-slate-500">{card.label}</p>
                    <p className="text-lg font-semibold text-slate-800">{card.value}</p>
                  </div>
                </CardBody>
              </Card>
            )
          })}
        </div>
      )}

      {/* Filters */}
      <Card className="mb-6">
        <CardBody>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
            <Select
              label="Status"
              value={statusFilter}
              onChange={(e) => {
                setStatusFilter(e.target.value)
                setCurrentPage(1) // Reset to first page when filter changes
              }}
              options={[
                { value: '', label: 'All Status' },
                { value: 'active', label: 'Active' },
                { value: 'closed', label: 'Closed' },
              ]}
            />
            <div className="flex items-end">
              <Button
                variant="secondary"
                onClick={() => {
                  setStatusFilter('')
                  setCurrentPage(1) // Reset to first page when clearing filters
                }}
                className="w-full"
              >
                Clear Filters
              </Button>
            </div>
          </div>
        </CardBody>
      </Card>

      {/* Loans Table */}
      <Card>
        <CardHeader title="Loan History" subtitle={`Total: ${loans.length} records`} />
        <CardBody className="p-0">
          {loans.length === 0 ? (
            <div className="px-5 py-8 text-center">
              <p className="text-sm text-slate-500">No loans found</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="border-b border-slate-200 bg-slate-50">
                  <tr>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Issue Date</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Amount</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Remaining</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Due Date</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {loans.map((loan) => (
                    <tr key={loan.id} className="hover:bg-slate-50 cursor-pointer" onClick={() => navigate(`/member/loans/${loan.id}/passbook`)}>
                      <td className="px-5 py-4 font-medium text-slate-800">
                        {formatDate(loan.issueDate)}
                      </td>
                      <td className="px-5 py-4 text-slate-600">{formatCurrency(loan.amount)}</td>
                      <td className="px-5 py-4 text-slate-600">{formatCurrency(loan.remaining)}</td>
                      <td className="px-5 py-4 text-slate-600">
                        {formatDate(loan.dueDate)}
                      </td>
                      <td className="px-5 py-4">
                        <Badge variant={loan.status === 'active' ? 'success' : 'slate'}>
                          {loan.status}
                        </Badge>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardBody>
      </Card>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="mt-4 flex items-center justify-between">
          <Button
            variant="secondary"
            onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
            disabled={currentPage === 1}
          >
            Previous
          </Button>
          <span className="text-sm text-slate-600">
            Page {currentPage} of {totalPages}
          </span>
          <Button
            variant="secondary"
            onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
          >
            Next
          </Button>
        </div>
      )}

      {/* Loan Requests */}
      <Card className="mt-6">
        <CardHeader title="My Loan Requests" subtitle="Track your submitted loan applications" />
        <CardBody className="p-0">
          {loanRequestsLoading ? (
            <div className="flex items-center justify-center py-8">
              <Loader label="Loading requests…" />
            </div>
          ) : loanRequests.length === 0 ? (
            <div className="px-5 py-8 text-center">
              <p className="text-sm text-slate-500">No loan requests yet</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="border-b border-slate-200 bg-slate-50">
                  <tr>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Request Date</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Amount</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Month Required</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Queue</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Expected Return</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Purpose</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Status</th>
                    <th className="px-5 py-3 text-left font-semibold text-slate-700">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {loanRequests.map((req) => (
                    <tr key={req.id} className="hover:bg-slate-50">
                      <td className="px-5 py-4 text-slate-600">{formatDate(req.createdAt)}</td>
                      <td className="px-5 py-4 font-medium text-slate-800">{formatCurrency(req.amount)}</td>
                      <td className="px-5 py-4 text-slate-600">{formatMonth(req.monthRequired)}</td>
                      <td className="px-5 py-4 text-slate-600">
                        {req.status === 'pending' && req.position ? (
                          <div>
                            <span className="font-medium text-slate-800">#{req.position}{req.queueTotal ? ` of ${req.queueTotal}` : ''}</span>
                            {req.fundingAhead > 0 && (
                              <p className="text-xs text-slate-400">{formatCurrency(req.fundingAhead)} ahead</p>
                            )}
                          </div>
                        ) : (
                          <span className="text-xs text-slate-400">—</span>
                        )}
                      </td>
                      <td className="px-5 py-4 text-slate-600">{req.expectedReturn ? formatDate(req.expectedReturn) : '—'}</td>
                      <td className="px-5 py-4 text-slate-600 capitalize">{req.purpose}</td>
                      <td className="px-5 py-4">
                        <Badge variant={statusBadgeVariant(req.status)}>{req.status}</Badge>
                        {req.status === 'pending' && req.waiting && (
                          <span className="mt-1 flex items-center gap-1 text-xs text-amber-600">
                            <FiClock className="h-3 w-3" /> Waiting for funds
                          </span>
                        )}
                        {req.status === 'rejected' && req.adminNotes && (
                          <p className="mt-1 max-w-[200px] text-xs text-slate-400">{req.adminNotes}</p>
                        )}
                      </td>
                      <td className="px-5 py-4">
                        {(req.status === 'pending' || req.status === 'approved') ? (
                          <button
                            type="button"
                            onClick={() => handleWithdraw(req.id)}
                            className="rounded-md border border-red-200 bg-red-50 px-2.5 py-1 text-xs font-medium text-red-700 transition-colors hover:bg-red-100 hover:text-red-800"
                          >
                            Withdraw
                          </button>
                        ) : (
                          <span className="text-xs text-slate-400">—</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardBody>
      </Card>

    </div>
  )
}
